import { test, before, after } from 'node:test'
import assert from 'node:assert/strict'
import { createServer } from 'node:http'
import { createApp } from '../src/app.mjs'

// Hand-written in-process double for the pricing downstream (priceOf(sku) -> euros).
const prices = { A: 10, B: 25, C: 0.1, D: 33.4, E: 10.1 }
const pricing = { priceOf: async (sku) => prices[sku] }

let server, base
before(async () => {
  server = createServer(createApp({ pricing }))
  await new Promise((r) => server.listen(0, r))
  base = `http://localhost:${server.address().port}`
})
after(() => server.close())

const post = (body, raw) => fetch(`${base}/orders`, { method: 'POST', body: raw ?? JSON.stringify(body) })
const total = async (items) => {
  const res = await post({ items })
  assert.equal(res.status, 201)
  return (await res.json()).total
}

test('POST /orders 201: shape, headers, sequential string ids', async () => {
  const items = [{ sku: 'A', qty: 2 }]
  const res = await post({ items })
  assert.equal(res.status, 201)
  assert.equal(res.headers.get('content-type'), 'application/json')
  const a = await res.json()
  assert.deepEqual({ ...a, id: undefined }, { id: undefined, items, total: 20 })
  assert.equal(typeof a.id, 'string')
  const b = await (await post({ items })).json()
  assert.equal(Number(b.id), Number(a.id) + 1)
})

test('total without discount: sum of price*qty', async () => {
  assert.equal(await total([{ sku: 'A', qty: 1 }, { sku: 'B', qty: 2 }]), 60)
})

test('discount threshold: exactly 100 is NOT discounted, above 100 gets 10% off', async () => {
  assert.equal(await total([{ sku: 'A', qty: 10 }]), 100)
  assert.equal(await total([{ sku: 'A', qty: 10 }, { sku: 'C', qty: 1 }]), 90) // 100.1 -> 90.09 -> 90
  assert.equal(await total([{ sku: 'B', qty: 5 }]), 112) // 125 -> 112.5 -> 112
})

test('discount is a flat 10% at every size; larger orders', async () => {
  assert.equal(await total([{ sku: 'A', qty: 100 }]), 900)
  assert.equal(await total([{ sku: 'B', qty: 1000 }]), 22500)
})

test('CHARACTERIZATION: current behaviour may be unintended — total is truncated (Math.floor) after discount, never rounded, and cents are lost', async () => {
  assert.equal(await total([{ sku: 'E', qty: 10 }]), 90) // 101 -> 90.9 -> 90
  assert.equal(await total([{ sku: 'C', qty: 3 }]), 0) // 0.30000000000000004 -> 0
  assert.equal(await total([{ sku: 'D', qty: 3 }]), 90) // 100.2 -> 90.18 -> 90
})

test('CHARACTERIZATION: current behaviour may be unintended — unknown sku yields NaN total, serialised as null, still 201', async () => {
  const res = await post({ items: [{ sku: 'ZZ', qty: 1 }] })
  assert.equal(res.status, 201)
  assert.equal((await res.json()).total, null)
})

test('CHARACTERIZATION: current behaviour may be unintended — negative qty lowers the total, no validation', async () => {
  assert.equal(await total([{ sku: 'A', qty: -3 }]), -30)
})

test('POST /orders 400: missing, empty, non-array items and invalid JSON', async () => {
  for (const res of [await post({}), await post({ items: [] }), await post({ items: 'x' }), await post(null, '{bad')]) {
    assert.equal(res.status, 400)
    assert.deepEqual(await res.json(), { error: 'items required' })
  }
})

test('GET /orders/:id returns the stored order', async () => {
  const created = await (await post({ items: [{ sku: 'B', qty: 5 }] })).json()
  const res = await fetch(`${base}/orders/${created.id}`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), created)
})

test('CHARACTERIZATION: current behaviour may be unintended — unknown order id returns 200 with an error body, not 404', async () => {
  const res = await fetch(`${base}/orders/does-not-exist`)
  assert.equal(res.status, 200)
  assert.deepEqual(await res.json(), { error: 'not found' })
})

test('unknown routes and methods return 404 no route', async () => {
  for (const [m, p] of [['GET', '/nope'], ['DELETE', '/orders/1'], ['GET', '/orders']]) {
    const res = await fetch(base + p, { method: m })
    assert.equal(res.status, 404)
    assert.deepEqual(await res.json(), { error: 'no route' })
  }
})
E
